// ── Helpers ───────────────────────────────────────────────────────────────────

function chunks(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
  return out;
}

async function upsertTable(table, rows, label) {
  console.log(`\n→ ${label} (${rows.length} rows)`);
  for (const batch of chunks(rows, 50)) {
    const { error } = await supabase.from(table).upsert(batch, { onConflict: 'id' });
    if (error) { console.error(`  ✗ ${error.message}`); process.exit(1); }
    process.stdout.write('.');
  }
  console.log(` ✓`);
}

// ── Migration ─────────────────────────────────────────────────────────────────

async function migrate() {
  console.log('Starting CRM → Cerebro migration...');

  // Order matters: clients first (FK dependency)
  await upsertTable('clients',    clients,    'Clients');
  await upsertTable('team_users', teamUsers,  'Team Users');
  await upsertTable('projects',   projects,   'Projects');
  await upsertTable('quotes',     quotes,     'Quotes');
  await upsertTable('financials', financials, 'Financials');
  await upsertTable('tasks',      tasks,      'Tasks');

  console.log('\n✅ Migration complete!');
  console.log(`   clients: ${clients.length}`);
  console.log(`   team_users: ${teamUsers.length}`);
  console.log(`   projects: ${projects.length}`);
  console.log(`   quotes: ${quotes.length}`);
  console.log(`   financials: ${financials.length}`);
  console.log(`   tasks: ${tasks.length}`);
}

migrate().catch(err => { console.error('Fatal:', err); process.exit(1); });
